sys_ui_page.client_script:
window.addEventListener(
    'load',
    function() {
        loadManagerDashboard();
    }
);


function loadManagerDashboard() {

    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/manager-dashboard',
        {
            method: 'GET',
            credentials: 'same-origin',
            headers: {
                'X-UserToken':
                    window.g_ck || ''
            }
        }
    )

    .then(function(response) {
        return response.json();
    })

    .then(function(data) {

        if (
            !data.result ||
            !data.result.success
        ) {
            throw new Error(
                'Unable to load attendance dashboard.'
            );
        }

        renderDashboard(
            data.result
        );

    })

    .catch(function(error) {

        var loading =
            document.getElementById(
                'loadingBox'
            );

        loading.className =
            'error';

        loading.textContent =
            error.message;
    });

}


function renderDashboard(data) {

    document.getElementById(
        'loadingBox'
    ).style.display =
        'none';


    document.getElementById(
        'managerCard'
    ).style.display =
        'block';


    document.getElementById(
        'dashboardContent'
    ).style.display =
        'block';


    setText(
        'managerName',
        data.manager
    );


    setText(
        'dashboardDate',
        'Today • ' +
        formatDate(
            data.today
        )
    );


    var today =
        data.today_summary || {};


    setText(
        'todayTotal',
        today.total_employees || 0
    );

    setText(
        'todayCheckedIn',
        today.checked_in || 0
    );

    setText(
        'todayCheckedOut',
        today.checked_out || 0
    );

    setText(
        'todayNotCheckedIn',
        today.not_checked_in || 0
    );

    setText(
        'todayLate',
        today.late || 0
    );

    setText(
        'todayPresent',
        today.present || 0
    );

    setText(
        'todayHalfDay',
        today.half_day || 0
    );

    setText(
        'todayInsufficient',
        today.insufficient_hours || 0
    );


    var seven =
        data.seven_day_summary || {};


    setText(
        'sevenDayPeriod',
        formatDate(
            seven.from
        ) +
        ' to ' +
        formatDate(
            seven.to
        )
    );


    setText(
        'sevenRecords',
        seven.attendance_records || 0
    );

    setText(
        'sevenPresent',
        seven.present || 0
    );

    setText(
        'sevenLate',
        seven.late || 0
    );

    setText(
        'sevenInsufficient',
        seven.insufficient_hours || 0
    );

    setText(
        'sevenHalfDay',
        seven.half_day || 0
    );

    setText(
        'sevenAvgWork',
        seven.average_working_minutes || 0
    );

    setText(
        'sevenLateMinutes',
        seven.total_late_minutes || 0
    );


    renderEmployees(
        data.employees || []
    );

}


function renderEmployees(
    employees
) {

    var container =
        document.getElementById(
            'employeeContainer'
        );


    if (
        !employees ||
        employees.length === 0
    ) {

        container.innerHTML =
            '<div class="employee-card">' +
            'No employees assigned.' +
            '</div>';

        return;

    }


    var html = '';


    for (
        var i = 0;
        i < employees.length;
        i++
    ) {

        var employee =
            employees[i];


        var status =
            employee.status ||
            'not_checked_in';


        var statusInfo =
            getStatusInfo(
                status
            );


        html +=

            '<div class="employee-card">' +

                '<div class="employee-name">' +
                    escapeHtml(
                        employee.employee ||
                        '-'
                    ) +
                '</div>' +

                '<div class="employee-meta">' +

                    escapeHtml(
                        employee.employee_code ||
                        'No Employee Code'
                    ) +

                    ' • ' +

                    escapeHtml(
                        employee.department ||
                        'No Department'
                    ) +

                    ' • ' +

                    escapeHtml(
                        employee.shift ||
                        '-'
                    ) +

                '</div>' +


                '<div class="employee-status ' +
                    statusInfo.css +
                '">' +

                    escapeHtml(
                        statusInfo.label
                    ) +

                '</div>' +


                '<div class="employee-time-grid">' +

                    buildEmployeeStat(
                        'Check In',
                        formatDateTime(
                            employee.check_in
                        )
                    ) +

                    buildEmployeeStat(
                        'Check Out',
                        formatDateTime(
                            employee.check_out
                        )
                    ) +

                    buildEmployeeStat(
                        'Working',
                        (
                            employee.working_minutes ||
                            0
                        ) +
                        ' min'
                    ) +

                    buildEmployeeStat(
                        'Late',
                        (
                            employee.late_minutes ||
                            0
                        ) +
                        ' min'
                    ) +

                '</div>' +

            '</div>';

    }


    container.innerHTML =
        html;

}


function getStatusInfo(
    status
) {

    if (
        status === 'present'
    ) {

        return {
            label: 'Present',
            css: 'status-present'
        };

    }


    if (
        status === 'late'
    ) {

        return {
            label: 'Late',
            css: 'status-late'
        };

    }


    if (
        status === 'half_day'
    ) {

        return {
            label: 'Half Day',
            css: 'status-warning'
        };

    }


    if (
        status ===
        'insufficient_hours'
    ) {

        return {
            label: 'Insufficient Hours',
            css: 'status-warning'
        };

    }


    return {
        label: 'Not Checked In',
        css: 'status-none'
    };

}


function buildEmployeeStat(
    label,
    value
) {

    return (

        '<div class="employee-stat">' +

            '<div class="employee-stat-label">' +
                escapeHtml(label) +
            '</div>' +

            '<div class="employee-stat-value">' +
                escapeHtml(
                    String(value)
                ) +
            '</div>' +

        '</div>'

    );

}


function formatDate(
    value
) {

    if (!value) {
        return '-';
    }


    var parts =
        value.split('-');


    if (
        parts.length !== 3
    ) {
        return value;
    }


    return (
        parts[2] +
        '-' +
        parts[1] +
        '-' +
        parts[0]
    );

}


function formatDateTime(
    value
) {

    if (!value) {
        return '-';
    }


    var parts =
        value.split(' ');


    if (
        parts.length < 2
    ) {
        return value;
    }


    return (
        formatDate(
            parts[0]
        ) +
        ' ' +
        formatTime(
            parts[1]
        )
    );

}


function formatTime(
    value
) {

    if (!value) {
        return '-';
    }


    var parts =
        value.split(':');


    var hour =
        parseInt(
            parts[0],
            10
        );


    var minute =
        parts[1];


    var suffix =
        hour >= 12
            ? 'PM'
            : 'AM';


    hour =
        hour % 12;


    if (
        hour === 0
    ) {
        hour = 12;
    }


    return (
        hour +
        ':' +
        minute +
        ' ' +
        suffix
    );

}


function setText(
    id,
    value
) {

    var element =
        document.getElementById(
            id
        );


    if (element) {

        element.textContent =
            value;

    }

}


function escapeHtml(
    value
) {

    return String(
        value === null ||
        value === undefined
            ? ''
            : value
    )

    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

}
